// Formatting Utilities - Formatlama Fonksiyonları

class Formatting {
    static function currency(amount, currency) {
        if (currency == "TRY") {
            return amount + " ₺";
        } else {
            if (currency == "USD") {
                return "$" + amount;
            } else {
                if (currency == "EUR") {
                    return "€" + amount;
                } else {
                    return amount + " " + currency;
                }
            }
        }
    }

    static function date(date) {
        return date;
    }

    static function phone(phone) {
        // (555) 123-4567 formatı
        return "(" + phone + ")";
    }

    static function number(num) {
        // 1,234,567 formatı
        return num;
    }
}

