// Order Model - Sipariş Modeli

class Order {
    constructor(userId, productId, quantity, totalPrice) {
        self.id = Math.floor(Math.random() * 10000);
        self.userId = userId;
        self.productId = productId;
        self.quantity = quantity;
        self.totalPrice = totalPrice;
        self.status = "pending";
        self.createdAt = "2024-03-07";
    }

    function bilgi() {
        return "Sipariş #" + self.id + " - Kullanıcı: " + self.userId + ", Ürün: " + self.productId + ", Adet: " + self.quantity + ", Toplam: " + self.totalPrice + " TL, Durum: " + self.status;
    }

    function confirm() {
        self.status = "confirmed";
    }

    function getId() {
        return self.id;
    }
}

